const CURRICULUM_EASY_LEVELS: &[(&str, &[&str])] = &[
    ("lvl-01-corner", &["#####", "#@$.#", "#####"]),
    ("lvl-02-corridor", &["#######", "#@$.. #", "#######"]),
    ("lvl-03-t", &["#####", "#@  #", "# $ #", "#  .#", "#####"]),
