    ("seed-105", &["#######", "#@ $  #", "#  $ .#", "#    .#", "#######"]),
    ("seed-106", &["######", "#@   #", "###$ #", "#  . #", "######"]),
    ("seed-107", &["#######", "#@    #", "# $$  #", "# ..  #", "#######"]),
