// Scenario runner binary for Sokoban
// Reads ONE scenario entry as JSON on stdin, writes {"events": [...]} on stdout.

use std::collections::HashMap;
use std::io::Read;

use sokoban_scenario::engine::SokobanEngine;
use sokoban_scenario::task_resolve::resolve_task;

fn main() {
    let mut input = String::new();
    std::io::stdin().read_to_string(&mut input).expect("stdin read");

    let entry: HashMap<String, serde_json::Value> =
        serde_json::from_str(&input).expect("JSON parse");

    let scenario_id = entry
        .get("scenario_id")
        .and_then(|v| v.as_str())
        .unwrap_or("manual")
        .to_string();

    let task = if entry.contains_key("task") {
        entry.get("task").unwrap().clone()
    } else {
        serde_json::json!({
            "schema": "gamebench.task.sokoban.v1",
            "task_id": scenario_id,
            "seed": entry.get("seed").and_then(|v| v.as_i64()).unwrap_or(0),
            "map": entry.get("map").unwrap().clone(),
            "rules": entry.get("rules").cloned().unwrap_or(serde_json::json!({"base": "sparse_sokoban"})),
            "readouts": {"symbolic": "ascii_annotated", "visual": false},
            "checkpoint_every_n_steps": 1,
        })
    };

    let task_map: HashMap<String, serde_json::Value> = task
        .as_object()
        .map(|obj| obj.iter().map(|(k, v)| (k.clone(), v.clone())).collect())
        .unwrap_or_default();

    let actions: Vec<String> = entry
        .get("actions")
        .and_then(|v| v.as_array())
        .map(|arr| {
            arr.iter()
                .map(|v| v.as_str().unwrap_or("").to_string())
                .collect()
        })
        .unwrap_or_default();

    let rt = resolve_task(&task_map, None);
    let mut engine = SokobanEngine::new();
    engine.reset(rt);

    for action in &actions {
        if engine.private.terminated || engine.private.truncated {
            break;
        }
        engine.step(action);
    }

    let events = engine.nev.legacy_strings();
    let output = serde_json::json!({ "events": events });
    println!("{}", serde_json::to_string(&output).unwrap());
}

// Engine - ported from gold_python/engine.py

use crate::nev::{EventKind, EventRecord, EventSeverity, NevLog};
use crate::state::{PrivateState, PublicState};
use crate::task_resolve::{ResolvedTask, BOX, BOX_ON_TARGET, FLOOR, PLAYER, PLAYER_ON_TARGET, TARGET, WALL};

use sha2::{Sha256, Digest};
use std::collections::{BTreeSet, HashMap};

pub const DIRS: &[(&str, (i32, i32))] = &[
    ("up", (-1, 0)),
    ("down", (1, 0)),
    ("left", (0, -1)),
    ("right", (0, 1)),
];

pub fn episode_id_for_task(task_id: &str, seed: i32, config_hash: &str) -> String {
    let input = format!("gamebench.sokoban-singleplayer.episode:{}:{}:{}", task_id, seed, config_hash);
    let mut hasher = Sha256::new();
    hasher.update(input.as_bytes());
    let digest = format!("{:x}", hasher.finalize());
    digest[..32].to_string()
}

pub struct SokobanEngine {
    pub resolved: Option<ResolvedTask>,
    pub room_fixed: Vec<Vec<i32>>,
    pub room_state: Vec<Vec<i32>>,
    pub player: (i32, i32),
    pub boxes: BTreeSet<(i32, i32)>,
    pub goals: BTreeSet<(i32, i32)>,
    pub public: PublicState,
    pub private: PrivateState,
    pub nev: NevLog,
}

impl SokobanEngine {
    pub fn new() -> Self {
        Self {
            resolved: None,
            room_fixed: Vec::new(),
            room_state: Vec::new(),
            player: (0, 0),
            boxes: BTreeSet::new(),
            goals: BTreeSet::new(),
            public: PublicState::new(Vec::new(), (0, 0), Vec::new(), 0, false),
            private: PrivateState::new(String::new(), String::new(), String::new(), 0, String::new()),
            nev: NevLog::new(),
        }
    }

    pub fn reset(&mut self, resolved_task: ResolvedTask) {
        self.resolved = Some(resolved_task);
        let rt = self.resolved.as_ref().unwrap();
        self.room_fixed = rt.room_fixed.clone();
        self.player = rt.player;
        self.boxes = rt.boxes.iter().cloned().collect();
        self.goals = rt.goals.iter().cloned().collect();
        self.room_state = self.compose_room_state();
        self.public = self.public_state();

        let episode_id = episode_id_for_task(&rt.task_id, rt.seed, &rt.config_hash);
        self.private = PrivateState::new(
            episode_id,
            rt.task_id.clone(),
            rt.puzzle_id.clone(),
            rt.seed,
            rt.config_hash.clone(),
        );
        self.nev = NevLog::new();

        self.append_nev(
            EventKind::TaskResolved,
            format!("TaskResolved({},{})", rt.puzzle_id, rt.config_hash),
            EventSeverity::Info,
            None,
            None,
            Some({
                let mut p = HashMap::new();
                p.insert("resolved".to_string(), rt.to_json_value());
                p
            }),
        );
    }

    fn public_state(&self) -> PublicState {
        let boxes_sorted: Vec<(i32, i32)> = self.boxes.iter().cloned().collect();
        let boxes_on_target = self.boxes.iter().filter(|b| self.goals.contains(b)).count() as i32;
        PublicState::new(
            self.room_state.clone(),
            self.player,
            boxes_sorted,
            boxes_on_target,
            self.private.terminated || self.private.truncated,
        )
    }

    fn compose_room_state(&self) -> Vec<Vec<i32>> {
        let mut state: Vec<Vec<i32>> = Vec::new();
        for (r, fixed_row) in self.room_fixed.iter().enumerate() {
            let mut row: Vec<i32> = Vec::new();
            for (c, &fixed) in fixed_row.iter().enumerate() {
                let pos = (r as i32, c as i32);
                if fixed == WALL {
                    row.push(WALL);
                } else if pos == self.player {
                    row.push(if fixed == TARGET { PLAYER_ON_TARGET } else { PLAYER });
                } else if self.boxes.contains(&pos) {
                    row.push(if fixed == TARGET { BOX_ON_TARGET } else { BOX });
                } else {
                    row.push(if fixed == TARGET { TARGET } else { FLOOR });
                }
            }
            state.push(row);
        }
        state
    }

    fn is_wall(&self, r: i32, c: i32) -> bool {
        if r < 0 || c < 0 || r >= self.room_fixed.len() as i32 || c >= self.room_fixed[0].len() as i32 {
            return true;
        }
        self.room_fixed[r as usize][c as usize] == WALL
    }

    fn is_solved(&self) -> bool {
        self.goals.iter().all(|goal| self.boxes.contains(goal))
    }

    fn reward(&self, key: &str) -> f64 {
        match &self.resolved {
            Some(rt) => *rt.rewards.get(key).unwrap_or(&0.0),
            None => 0.0,
        }
    }

    pub fn step(&mut self, action: &str) {
        let action = action.trim().to_lowercase();

        // Check if action is valid
        let dir = DIRS.iter().find(|(name, _)| *name == action);
        if dir.is_none() {
            self.blocked(&action, "unknown_action", 0.0);
            return;
        }
        if self.private.terminated || self.private.truncated {
            self.blocked(&action, "terminal", 0.0);
            return;
        }

        let prev_public = self.public_state();
        let prev_on_targets = prev_public.boxes_on_target;

        let &(_, (dr, dc)) = dir.unwrap();
        let (pr, pc) = self.player;
        let (nr, nc) = (pr + dr, pc + dc);

        let mut reward = self.reward("step");

        if self.is_wall(nr, nc) {
            self.blocked(&action, "wall", reward);
            return;
        }

        let mut pushed = false;
        if self.boxes.contains(&(nr, nc)) {
            let (br, bc) = (nr + dr, nc + dc);
            if self.is_wall(br, bc) || self.boxes.contains(&(br, bc)) {
                self.blocked(&action, "box_blocked", reward);
                return;
            }
            self.boxes.remove(&(nr, nc));
            self.boxes.insert((br, bc));
            pushed = true;
            reward += self.reward("push");
        }

        self.player = (nr, nc);
        self.private.step_index += 1;
        self.room_state = self.compose_room_state();
        self.public = self.public_state();
        self.private.reward_last = reward;
        self.private.total_reward += reward;

        // ActionApplied event
        self.append_nev(
            EventKind::ActionApplied,
            format!("ActionApplied({},step={})", action, self.private.step_index),
            EventSeverity::Info,
            Some(action.clone()),
            Some(self.public.diff(&prev_public)),
            Some({
                let mut p = HashMap::new();
                p.insert("action".to_string(), serde_json::json!(action));
                p.insert("pushed".to_string(), serde_json::json!(pushed));
                p
            }),
        );

        if pushed {
            let boxes_sorted: Vec<Vec<i32>> = self.boxes.iter().map(|(r, c)| vec![*r, *c]).collect();
            self.append_nev(
                EventKind::PushApplied,
                format!("PushApplied({},boxes_on_target={})", action, self.public.boxes_on_target),
                EventSeverity::Info,
                Some(action.clone()),
                None,
                Some({
                    let mut p = HashMap::new();
                    p.insert("boxes".to_string(), serde_json::json!(boxes_sorted));
                    p
                }),
            );
            self.unlock("first_push");
        }

        if self.public.boxes_on_target > prev_on_targets {
            let box_reward = self.reward("box_on_target");
            self.private.reward_last += box_reward;
            self.private.total_reward += box_reward;
            self.append_nev(
                EventKind::BoxOnTarget,
                format!("BoxOnTarget({}/{})", self.public.boxes_on_target, self.goals.len()),
                EventSeverity::Info,
                None,
                None,
                Some({
                    let mut p = HashMap::new();
                    p.insert("boxes_on_target".to_string(), serde_json::json!(self.public.boxes_on_target));
                    p.insert("goals".to_string(), serde_json::json!(self.goals.len()));
                    p
                }),
            );
            self.unlock("first_box_on_target");
        }

        // Check reward_last for RewardDelta
        if self.private.reward_last != 0.0 {
            self.append_nev(
                EventKind::RewardDelta,
                format!("RewardDelta({:.2},total={:.2})", self.private.reward_last, self.private.total_reward),
                EventSeverity::Info,
                None,
                None,
                Some({
                    let mut p = HashMap::new();
                    p.insert("delta".to_string(), serde_json::json!(self.private.reward_last));
                    p.insert("total".to_string(), serde_json::json!(self.private.total_reward));
                    p
                }),
            );
        }

        // No monty_reward for sparse_sokoban default, skip monty check

        // Check solved
        if self.is_solved() {
            let goal_reward = self.reward("goal");
            self.private.reward_last += goal_reward;
            self.private.total_reward += goal_reward;
            self.private.terminated = true;
            self.public.done = true;
            self.append_nev(
                EventKind::LevelComplete,
                format!("LevelComplete({})", self.private.step_index),
                EventSeverity::Info,
                None,
                None,
                Some({
                    let mut p = HashMap::new();
                    p.insert("steps".to_string(), serde_json::json!(self.private.step_index));
                    p
                }),
            );
            self.unlock("level_complete");
            self.append_nev(
                EventKind::Terminal,
                "Terminal(success)".to_string(),
                EventSeverity::Info,
                None,
                None,
                Some({
                    let mut p = HashMap::new();
                    p.insert("reason".to_string(), serde_json::json!("success"));
                    p
                }),
            );
        } else if let Some(ref rt) = self.resolved {
            if self.private.step_index >= rt.max_steps {
                self.private.truncated = true;
                self.public.done = true;
                self.append_nev(
                    EventKind::EpisodeTruncated,
                    format!("EpisodeTruncated(max_steps={})", rt.max_steps),
                    EventSeverity::Info,
                    None,
                    None,
                    Some({
                        let mut p = HashMap::new();
                        p.insert("max_steps".to_string(), serde_json::json!(rt.max_steps));
                        p
                    }),
                );
                self.append_nev(
                    EventKind::Terminal,
                    "Terminal(truncated)".to_string(),
                    EventSeverity::Info,
                    None,
                    None,
                    Some({
                        let mut p = HashMap::new();
                        p.insert("reason".to_string(), serde_json::json!("truncated"));
                        p
                    }),
                );
            }
        }
    }

    fn blocked(&mut self, action: &str, reason: &str, base_reward: f64) {
        self.private.step_index += 1;

        let severity = match &self.resolved {
            Some(rt) if rt.errors.get("mode").and_then(|v| v.as_str()) == Some("strict") => {
                EventSeverity::Error
            }
            _ => EventSeverity::Warn,
        };

        self.private.reward_last = base_reward + self.reward("blocked");
        self.private.total_reward += self.private.reward_last;

        self.append_nev(
            EventKind::PushBlocked,
            format!("PushBlocked({},{},step={})", action, reason, self.private.step_index),
            severity,
            Some(action.to_string()),
            None,
            Some({
                let mut p = HashMap::new();
                p.insert("reason".to_string(), serde_json::json!(reason));
                p
            }),
        );

        if severity == EventSeverity::Error {
            self.append_nev(
                EventKind::RuleViolation,
                format!("RuleViolation({})", reason),
                severity,
                Some(action.to_string()),
                None,
                Some({
                    let mut p = HashMap::new();
                    p.insert("reason".to_string(), serde_json::json!(reason));
                    p
                }),
            );
        }

        if self.private.reward_last != 0.0 {
            self.append_nev(
                EventKind::RewardDelta,
                format!("RewardDelta({:.2},total={:.2})", self.private.reward_last, self.private.total_reward),
                EventSeverity::Info,
                None,
                None,
                Some({
                    let mut p = HashMap::new();
                    p.insert("delta".to_string(), serde_json::json!(self.private.reward_last));
                    p.insert("total".to_string(), serde_json::json!(self.private.total_reward));
                    p
                }),
            );
        }

        if let Some(ref rt) = self.resolved {
            if self.private.step_index >= rt.max_steps {
                self.private.truncated = true;
                self.public.done = true;
                self.append_nev(
                    EventKind::EpisodeTruncated,
                    format!("EpisodeTruncated(max_steps={})", rt.max_steps),
                    EventSeverity::Info,
                    None,
                    None,
                    Some({
                        let mut p = HashMap::new();
                        p.insert("max_steps".to_string(), serde_json::json!(rt.max_steps));
                        p
                    }),
                );
                self.append_nev(
                    EventKind::Terminal,
                    "Terminal(truncated)".to_string(),
                    EventSeverity::Info,
                    None,
                    None,
                    Some({
                        let mut p = HashMap::new();
                        p.insert("reason".to_string(), serde_json::json!("truncated"));
                        p
                    }),
                );
            }
        }
    }

    fn append_nev(
        &mut self,
        kind: EventKind,
        message: String,
        severity: EventSeverity,
        action: Option<String>,
        transition: Option<HashMap<String, serde_json::Value>>,
        payload: Option<HashMap<String, serde_json::Value>>,
    ) {
        let record = EventRecord::new(
            self.private.step_index,
            self.private.step_index,
            self.private.episode_id.clone(),
            kind,
            severity,
            message,
            action,
            transition.map(|m| serde_json::json!(m)),
            payload.unwrap_or_default(),
        );
        self.nev.append(record);
    }

    fn unlock(&mut self, name: &str) {
        if self.private.achievements.contains(name) {
            return;
        }
        self.private.achievements.insert(name.to_string());
        self.append_nev(
            EventKind::AchievementUnlocked,
            format!("AchievementUnlocked({})", name),
            EventSeverity::Info,
            None,
            None,
            Some({
                let mut p = HashMap::new();
                p.insert("achievement".to_string(), serde_json::json!(name));
                p
            }),
        );
    }
}

