// === ASCII grid parsing ===

pub fn ascii_to_int_grids(
    rows: &[String],
) -> (Vec<Vec<i32>>, Vec<Vec<i32>>, Vec<(i32, i32)>, Vec<(i32, i32)>, (i32, i32)) {
    let width = rows.iter().map(|r| r.len()).max().unwrap_or(0);
    let mut room_fixed: Vec<Vec<i32>> = Vec::new();
    let mut room_state: Vec<Vec<i32>> = Vec::new();
    let mut goals: Vec<(i32, i32)> = Vec::new();
    let mut boxes: Vec<(i32, i32)> = Vec::new();
    let mut player: Option<(i32, i32)> = None;

    for (r, raw_row) in rows.iter().enumerate() {
        let mut fixed_row = Vec::new();
        let mut state_row = Vec::new();
        let padded = format!("{:width$}", raw_row, width = width);
        for (c, ch) in padded.chars().enumerate() {
            match ch {
                '#' => {
                    fixed_row.push(WALL);
                    state_row.push(WALL);
                }
                '.' | 'G' => {
                    fixed_row.push(TARGET);
                    state_row.push(TARGET);
                    goals.push((r as i32, c as i32));
                }
                '*' => {
                    fixed_row.push(TARGET);
                    state_row.push(BOX_ON_TARGET);
                    goals.push((r as i32, c as i32));
                    boxes.push((r as i32, c as i32));
                }
                '+' => {
                    fixed_row.push(TARGET);
                    state_row.push(PLAYER_ON_TARGET);
                    goals.push((r as i32, c as i32));
                    player = Some((r as i32, c as i32));
                }
                '$' => {
                    fixed_row.push(FLOOR);
                    state_row.push(BOX);
                    boxes.push((r as i32, c as i32));
                }
                '@' => {
                    fixed_row.push(FLOOR);
                    state_row.push(PLAYER);
                    player = Some((r as i32, c as i32));
                }
                _ => {
                    fixed_row.push(FLOOR);
                    state_row.push(FLOOR);
                }
            }
        }
        room_fixed.push(fixed_row);
        room_state.push(state_row);
    }

    let player = player.expect("sokoban map has no player");
    assert!(!goals.is_empty(), "sokoban map has no goals");
    assert!(!boxes.is_empty(), "sokoban map has no boxes");

    (room_fixed, room_state, goals, boxes, player)
}

pub fn grid_to_ascii(
    room_fixed: &[Vec<i32>],
    player: (i32, i32),
    boxes: &std::collections::BTreeSet<(i32, i32)>,
) -> Vec<String> {
    let mut rows = Vec::new();
    for (r, fixed_row) in room_fixed.iter().enumerate() {
        let mut chars = Vec::new();
        for (c, &fixed) in fixed_row.iter().enumerate() {
            let pos = (r as i32, c as i32);
            let on_target = fixed == TARGET;
            if fixed == WALL {
                chars.push('#');
            } else if pos == player {
                chars.push(if on_target { '+' } else { '@' });
            } else if boxes.contains(&pos) {
                chars.push(if on_target { '*' } else { '$' });
            } else if on_target {
                chars.push('.');
            } else {
                chars.push(' ');
            }
        }
        let s: String = chars.iter().collect();
        rows.push(s.trim_end().to_string());
    }
    rows
}

// === Deep merge helper ===

fn deep_merge_value(target: &mut serde_json::Value, source: &serde_json::Value) {
    match (target, source) {
        (serde_json::Value::Object(tgt), serde_json::Value::Object(src)) => {
            for (key, src_val) in src {
                if let Some(tgt_val) = tgt.get_mut(key) {
                    deep_merge_value(tgt_val, src_val);
                } else {
                    tgt.insert(key.clone(), src_val.clone());
                }
            }
        }
        (tgt, src) => {
            *tgt = src.clone();
        }
    }
}

// === Resolve rules ===

fn resolve_rules_value(rules_spec: &serde_json::Value) -> serde_json::Value {
    let mut merged = sparse_sokoban_rules_value();

    if let Some(overrides) = rules_spec.get("overrides") {
        deep_merge_value(&mut merged, overrides);
    }

    merged
}

// === Resolve map ===
// Matches Python gold's _resolve_map exactly (simplified version without JSON file loading)

fn resolve_map(map_spec: &serde_json::Value, seed: i32) -> (String, serde_json::Value, serde_json::Value) {
    let source = map_spec.get("source").and_then(|v| v.as_str()).unwrap_or("");

    if source == "inline" || map_spec.get("grid").is_some() {
        let grid_val = map_spec.get("grid").expect("inline map must have grid");
        let puzzle_id = map_spec
            .get("puzzle_id")
            .and_then(|v| v.as_str())
            .unwrap_or("inline")
            .to_string();
        let metadata = map_spec.get("metadata").cloned().unwrap_or(serde_json::json!({}));
        return (puzzle_id, grid_val.clone(), metadata);
    }

    let default_name = map_spec
        .get("use_default")
        .and_then(|v| v.as_str())
        .unwrap_or("curriculum_easy")
        .to_string();

    let levels = CURRICULUM_EASY_LEVELS;

    let has_seed = map_spec.get("seed").is_some() || seed != 0;
    let index = if has_seed {
        let s = map_spec.get("seed").and_then(|v| v.as_i64()).unwrap_or(seed as i64);
        (s as usize) % levels.len()
    } else {
        let idx = map_spec.get("index").and_then(|v| v.as_i64()).unwrap_or(0);
        (idx as usize) % levels.len()
    };

    let (id, grid_ref) = &levels[index];
    let grid_lines: Vec<String> = grid_ref.iter().map(|s| s.to_string()).collect();

    let puzzle_id = id.to_string();

    // Build metadata exactly matching Python gold:
    // chosen.get("name", chosen["id"]) -> since no "name" key, returns chosen["id"]
    // chosen.get("optimal_steps") -> since no key, returns None -> JSON null
    let opt_steps: Option<i32> = None;
    let metadata = serde_json::json!({
        "default": default_name,
        "index": index,
        "name": puzzle_id,
        "optimal_steps": opt_steps,
    });

    let grid_val = serde_json::json!(grid_lines);

    (puzzle_id, grid_val, metadata)
}

// === Main resolve function ===

pub fn resolve_task(task: &HashMap<String, serde_json::Value>, seed_override: Option<i32>) -> ResolvedTask {
    let seed = match seed_override {
        Some(s) => s,
        None => {
            task.get("seed")
                .and_then(|v| v.as_i64())
                .or_else(|| {
                    task.get("map")
                        .and_then(|m| m.get("seed"))
                        .and_then(|v| v.as_i64())
                })
                .unwrap_or(0) as i32
        }
    };

    let task_id = task
        .get("task_id")
        .and_then(|v| v.as_str())
        .unwrap_or("sokoban_manual")
        .to_string();

    let map_spec = task.get("map").cloned().unwrap_or(serde_json::json!({}));

    // Resolve map
    let (puzzle_id, grid_val, metadata) = resolve_map(&map_spec, seed);

    // Resolve rules
    let rules_spec = task.get("rules").cloned().unwrap_or(serde_json::json!({"base": "sparse_sokoban"}));
    let merged_rules = resolve_rules_value(&rules_spec);

    let grid_rows: Vec<String> = match &grid_val {
        serde_json::Value::Array(arr) => {
            arr.iter().map(|v| v.as_str().unwrap_or("").to_string()).collect()
        }
        _ => panic!("grid must be array"),
    };

    let (room_fixed, room_state, goals, boxes, player) = ascii_to_int_grids(&grid_rows);

    // Build the resolved dict for config_hash
    let mut resolved_map = serde_json::Map::new();
    resolved_map.insert("schema".to_string(), serde_json::json!("gamebench.task.sokoban.v1"));
    resolved_map.insert("task_id".to_string(), serde_json::json!(task_id));
    resolved_map.insert("seed".to_string(), serde_json::json!(seed));

    let mut map_entry = serde_json::Map::new();
    map_entry.insert("puzzle_id".to_string(), serde_json::json!(puzzle_id));
    map_entry.insert("grid".to_string(), grid_val.clone());
    map_entry.insert("metadata".to_string(), metadata.clone());
    resolved_map.insert("map".to_string(), serde_json::json!(map_entry));

    // Use the FULLY MERGED rules (with achievements, max_steps, etc.)
    resolved_map.insert("rules".to_string(), merged_rules.clone());

    let readouts = task
        .get("readouts")
        .cloned()
        .unwrap_or(serde_json::json!({"symbolic": "ascii_annotated", "visual": false}));
    resolved_map.insert("readouts".to_string(), readouts);

    let checkpoint_every_n_steps = task
        .get("checkpoint_every_n_steps")
        .and_then(|v| v.as_i64())
        .unwrap_or(1);
    resolved_map.insert("checkpoint_every_n_steps".to_string(), serde_json::json!(checkpoint_every_n_steps));

    // Serialize to canonical JSON string (sort_keys=True, separators=(",",":"))
    let canonical = serde_json::to_string(&serde_json::Value::Object(resolved_map.clone())).unwrap();
    let mut hasher = Sha256::new();
    hasher.update(canonical.as_bytes());
    let digest = format!("{:x}", hasher.finalize());
    let config_hash = format!("sha256:{}", digest);

    let max_steps = merged_rules
        .get("max_steps")
        .and_then(|v| v.as_i64())
        .unwrap_or(120) as i32;

    let rewards_map: HashMap<String, f64> = merged_rules
        .get("rewards")
        .and_then(|v| v.as_object())
        .map(|obj| {
            obj.iter()
                .map(|(k, v)| (k.clone(), v.as_f64().unwrap_or(0.0)))
                .collect()
        })
        .unwrap_or_default();

    let errors: HashMap<String, serde_json::Value> = merged_rules
        .get("errors")
        .and_then(|v| v.as_object())
        .map(|obj| obj.iter().map(|(k, v)| (k.clone(), v.clone())).collect())
        .unwrap_or_default();

    let curriculum: HashMap<String, serde_json::Value> = metadata
        .as_object()
        .map(|obj| obj.iter().map(|(k, v)| (k.clone(), v.clone())).collect())
        .unwrap_or_default();

    let monty_reward: HashMap<String, serde_json::Value> = HashMap::new();
    let resolved_json: HashMap<String, serde_json::Value> = resolved_map.into_iter().collect();

    ResolvedTask {
        task_id,
        puzzle_id,
        seed,
        config_hash,
        room_fixed,
        room_state,
        goals,
        boxes,
        player,
        max_steps,
        rewards: rewards_map,
        errors,
        curriculum,
        monty_reward,
        resolved_json,
    }
}

"""Agent-facing observation and action parsing helpers."""

from __future__ import annotations

import json
import re
from dataclasses import dataclass
from typing import Any


ACTION_WORDS = ("up", "down", "left", "right")
ACTION_TAG_RE = re.compile(r"<action>\s*(up|down|left|right)\s*</action>", re.IGNORECASE)
ACTION_LINE_RE = re.compile(r"\b(?:action|move|direction)\s*[:=]\s*(up|down|left|right)\b", re.IGNORECASE)
WORD_RE = re.compile(r"\b(up|down|left|right)\b", re.IGNORECASE)


@dataclass(frozen=True)
class ParsedAction:
    action: str
    invalid_parse: bool
    repaired: bool
    error: str | None = None

    def to_dict(self) -> dict[str, Any]:
        return {
            "action": self.action,
            "invalid_parse": self.invalid_parse,
            "repaired": self.repaired,
            "error": self.error,
        }


def parse_action_text(raw_text: str, valid_actions: list[str] | None = None) -> ParsedAction:
    """Parse ReAct/LM output into one Sokoban action.

    The parser is deliberately deterministic. If the text is malformed or names
    an invalid action, it repairs to the first valid action in canonical order.
    """

    valid = [action for action in ACTION_WORDS if not valid_actions or action in valid_actions]
    if not valid:
        return ParsedAction(action="", invalid_parse=True, repaired=False, error="no_valid_actions")

    text = str(raw_text or "").strip()
    candidates: list[str] = []
    for matcher in (ACTION_TAG_RE, ACTION_LINE_RE, WORD_RE):
        match = matcher.search(text)
        if match:
            candidates.append(match.group(1).lower())

    try:
        parsed = json.loads(text)
        if isinstance(parsed, dict):
            value = parsed.get("action", parsed.get("move", parsed.get("direction")))
            if value is not None:
                candidates.insert(0, str(value).lower().strip())
        elif isinstance(parsed, str):
            candidates.insert(0, parsed.lower().strip())
    except json.JSONDecodeError:
        pass

    for candidate in candidates:
        if candidate in valid:
            return ParsedAction(action=candidate, invalid_parse=False, repaired=False)
        if candidate in ACTION_WORDS:
            return ParsedAction(
                action=valid[0],
                invalid_parse=True,
                repaired=True,
                error=f"invalid_action:{candidate}",
            )
    return ParsedAction(action=valid[0], invalid_parse=True, repaired=True, error="no_action_found")


def format_agent_observation(readout: dict[str, Any], *, objective: str | None = None) -> dict[str, Any]:
    public = readout["public"]
    private = readout["private"]
    valid_actions = list(readout.get("valid_actions", []))
    remaining = max(0, int(private.get("max_steps", 0) or 0) - int(private.get("step_index", 0)))
    lines = [
        objective or "Push every box onto a target.",
        "",
        "Legend: # wall, @ player, $ box, . target, * box on target, + player on target.",
        "Board:",
        str(readout.get("ascii", "")),
        "",
        f"Valid actions: {', '.join(valid_actions) if valid_actions else 'none'}",
        f"Boxes on target: {public.get('boxes_on_target', 0)}",
        f"Reward total: {private.get('total_reward', 0.0):.2f}",
        f"Step: {private.get('step_index', 0)}",
    ]
    if remaining:
        lines.append(f"Steps remaining: {remaining}")
    lines.append('Reply with exactly one move as JSON, for example {"action":"right"}.')
    return {
        "observation_text": "\n".join(lines),
        "ascii": readout.get("ascii", ""),
        "valid_actions": valid_actions,
        "grid_hash": readout.get("grid_hash"),
        "public": public,
        "private": private,
    }

"""Small HTTP client for Sokoban gold services."""

from __future__ import annotations

import base64
from dataclasses import dataclass
from typing import Any

import httpx


@dataclass
class SokobanGoldClient:
    base_url: str
    timeout: float = 60.0

    def health(self) -> dict[str, Any]:
        return self._get("/health")

    def create_rollout(self, task: dict[str, Any], *, seed: int | None = None) -> dict[str, Any]:
        body: dict[str, Any] = {"task": task}
        if seed is not None:
            body["seed"] = seed
        return self._post("/rollouts", body)

    def step(self, rollout_id: str, action: str) -> dict[str, Any]:
        return self._post(f"/rollouts/{rollout_id}/step", {"action": action})

    def checkpoint(self, rollout_id: str) -> dict[str, Any]:
        return self._post(f"/rollouts/{rollout_id}/checkpoint", {})

    def restore(self, rollout_id: str, blob: bytes) -> dict[str, Any]:
        return self._post(f"/rollouts/{rollout_id}/restore", {"blob": base64.b64encode(blob).decode("ascii")})

    def simulate(self, rollout_id: str, blob: bytes, sequences: list[list[str]]) -> dict[str, Any]:
        return self._post(
            f"/rollouts/{rollout_id}/simulate",
            {"blob": base64.b64encode(blob).decode("ascii"), "sequences": sequences},
        )

    def readout(self, rollout_id: str) -> dict[str, Any]:
        return self._get(f"/rollouts/{rollout_id}/readout")

    def event_log(self, rollout_id: str) -> dict[str, Any]:
        return self._get(f"/rollouts/{rollout_id}/event_log")

    def _get(self, path: str) -> dict[str, Any]:
        with httpx.Client(timeout=self.timeout) as client:
            response = client.get(f"{self.base_url.rstrip('/')}{path}")
            response.raise_for_status()
            return response.json()

    def _post(self, path: str, body: dict[str, Any]) -> dict[str, Any]:
        with httpx.Client(timeout=self.timeout) as client:
            response = client.post(f"{self.base_url.rstrip('/')}{path}", json=body)
            response.raise_for_status()
            return response.json()

"""Shaped reward for pushes vs idle steps."""

from __future__ import annotations

from typing import Any


def score_transition(
    *,
    spec: dict[str, Any],
    event: str,
    pushed: bool = False,
    **_: Any,
) -> float:
    if event == "level_complete":
        return 0.0
    if pushed:
        return float(spec.get("push_bonus", 0.02))
    return float(spec.get("idle_penalty", -0.005))

"""Sokoban observations and symbolic readouts."""

from __future__ import annotations

import hashlib
from typing import Any

from task_resolve import grid_to_ascii


ACTIONS = ["up", "down", "left", "right"]


def ascii_board(room_fixed: list[list[int]], player: tuple[int, int], boxes: set[tuple[int, int]]) -> str:
    return "\n".join(grid_to_ascii(room_fixed, player, boxes))


def grid_hash(room_state: list[list[int]]) -> str:
    payload = "|".join(",".join(str(cell) for cell in row) for row in room_state)
    return hashlib.sha256(payload.encode()).hexdigest()[:16]


def project_readout(engine: Any) -> dict[str, Any]:
    private = engine.private.to_dict()
    if engine.resolved is not None:
        private["max_steps"] = engine.resolved.max_steps
    return {
        "ascii": ascii_board(engine.room_fixed, engine.player, engine.boxes),
        "valid_actions": engine.valid_actions(),
        "grid_hash": grid_hash(engine.room_state),
        "public": engine.public.to_dict(),
        "private": private,
    }

"""Render helpers for Sokoban v0."""

from __future__ import annotations

import struct
import zlib

from observations import ascii_board


COLORS = {
    "#": (45, 48, 54),
    " ": (238, 238, 232),
    ".": (246, 214, 92),
    "$": (171, 111, 62),
    "*": (80, 170, 105),
    "@": (80, 140, 220),
    "+": (80, 170, 220),
}


def render_ascii(engine: object) -> str:
    return ascii_board(engine.room_fixed, engine.player, engine.boxes)


def render_svg(engine: object, *, tile_size: int = 32) -> str:
    rows = render_ascii(engine).splitlines()
    width = max(len(row) for row in rows) if rows else 0
    height = len(rows)
    parts = [
        f'<svg xmlns="http://www.w3.org/2000/svg" width="{width * tile_size}" height="{height * tile_size}" viewBox="0 0 {width * tile_size} {height * tile_size}">'
    ]
    for r, row in enumerate(rows):
        for c, ch in enumerate(row.ljust(width)):
            color = COLORS.get(ch, COLORS[" "])
            parts.append(
                f'<rect x="{c * tile_size}" y="{r * tile_size}" width="{tile_size}" height="{tile_size}" fill="rgb({color[0]},{color[1]},{color[2]})"/>'
            )
            if ch in "$*@+":
                label = "P" if ch in "@+" else "B"
                parts.append(
                    f'<text x="{c * tile_size + tile_size / 2}" y="{r * tile_size + tile_size * 0.66}" text-anchor="middle" font-size="{tile_size * 0.5}" font-family="monospace" fill="white">{label}</text>'
                )
    parts.append("</svg>")
    return "".join(parts)


def render_png_bytes(engine: object, *, tile_size: int = 24) -> bytes:
    rows = render_ascii(engine).splitlines()
    width_tiles = max(len(row) for row in rows) if rows else 1
    height_tiles = max(len(rows), 1)
    width = width_tiles * tile_size
    height = height_tiles * tile_size
    raw = bytearray()
    for y in range(height):
        raw.append(0)
        tile_r = y // tile_size
        row = rows[tile_r].ljust(width_tiles) if tile_r < len(rows) else " " * width_tiles
        for x in range(width):
            ch = row[x // tile_size]
            raw.extend(COLORS.get(ch, COLORS[" "]))
    return _png(width, height, bytes(raw))


def _png(width: int, height: int, raw_scanlines: bytes) -> bytes:
    def chunk(kind: bytes, data: bytes) -> bytes:
        crc = zlib.crc32(kind + data) & 0xFFFFFFFF
        return struct.pack(">I", len(data)) + kind + data + struct.pack(">I", crc)

    return b"\x89PNG\r\n\x1a\n" + chunk(
        b"IHDR",
        struct.pack(">IIBBBBB", width, height, 8, 2, 0, 0, 0),
    ) + chunk(b"IDAT", zlib.compress(raw_scanlines)) + chunk(b"IEND", b"")

