// NEV log - ported from gold_python/core/nev.py

use serde::{Deserialize, Serialize};
use std::collections::HashMap;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum EventKind {
    TaskResolved,
    ActionApplied,
    PushApplied,
    PushBlocked,
    RuleViolation,
    BoxOnTarget,
    AchievementUnlocked,
    RewardDelta,
    LevelComplete,
    EpisodeTruncated,
    Terminal,
    Checkpoint,
}

impl EventKind {
    pub fn as_str(&self) -> &'static str {
        match self {
            EventKind::TaskResolved => "task_resolved",
            EventKind::ActionApplied => "action_applied",
            EventKind::PushApplied => "push_applied",
            EventKind::PushBlocked => "push_blocked",
            EventKind::RuleViolation => "rule_violation",
            EventKind::BoxOnTarget => "box_on_target",
            EventKind::AchievementUnlocked => "achievement_unlocked",
            EventKind::RewardDelta => "reward_delta",
            EventKind::LevelComplete => "level_complete",
            EventKind::EpisodeTruncated => "episode_truncated",
            EventKind::Terminal => "terminal",
            EventKind::Checkpoint => "checkpoint",
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum EventSeverity {
    Info,
    Warn,
    Error,
}

impl EventSeverity {
    pub fn as_str(&self) -> &'static str {
        match self {
            EventSeverity::Info => "info",
            EventSeverity::Warn => "warn",
            EventSeverity::Error => "error",
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct EventRecord {
    pub step_index: i32,
    pub sim_tick: i32,
    pub episode_id: String,
    #[serde(rename = "kind")]
    pub kind_str: String,
    #[serde(rename = "severity")]
    pub severity_str: String,
    pub message: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub action: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub transition: Option<serde_json::Value>,
    #[serde(default)]
    pub payload: HashMap<String, serde_json::Value>,
}

impl EventRecord {
    pub fn new(
        step_index: i32,
        sim_tick: i32,
        episode_id: String,
        kind: EventKind,
        severity: EventSeverity,
        message: String,
        action: Option<String>,
        transition: Option<serde_json::Value>,
        payload: HashMap<String, serde_json::Value>,
    ) -> Self {
        Self {
            step_index,
            sim_tick,
            episode_id,
            kind_str: kind.as_str().to_string(),
            severity_str: severity.as_str().to_string(),
            message,
            action,
            transition,
            payload,
        }
    }
}

#[derive(Debug, Clone)]
pub struct NevLog {
    pub events: Vec<EventRecord>,
}

impl NevLog {
    pub fn new() -> Self {
        Self { events: Vec::new() }
    }

    pub fn cursor(&self) -> usize {
        self.events.len()
    }

    pub fn append(&mut self, record: EventRecord) {
        self.events.push(record);
    }

    pub fn export(&self) -> Vec<EventRecord> {
        self.events.clone()
    }

    pub fn legacy_strings(&self) -> Vec<String> {
        self.events.iter().map(|e| e.message.clone()).collect()
    }
}

// State - ported from gold_python/state.py

use serde::{Deserialize, Serialize};
use std::collections::BTreeSet;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PublicState {
    pub room_state: Vec<Vec<i32>>,
    pub player: (i32, i32),
    pub boxes: Vec<(i32, i32)>,
    pub boxes_on_target: i32,
    pub done: bool,
}

impl PublicState {
    pub fn new(
        room_state: Vec<Vec<i32>>,
        player: (i32, i32),
        boxes: Vec<(i32, i32)>,
        boxes_on_target: i32,
        done: bool,
    ) -> Self {
        Self {
            room_state,
            player,
            boxes,
            boxes_on_target,
            done,
        }
    }

    pub fn to_json_value(&self) -> serde_json::Value {
        serde_json::json!({
            "room_state": self.room_state,
            "player": [self.player.0, self.player.1],
            "boxes": self.boxes.iter().map(|p| vec![p.0, p.1]).collect::<Vec<_>>(),
            "boxes_on_target": self.boxes_on_target,
            "done": self.done,
        })
    }

    pub fn diff(&self, other: &PublicState) -> HashMap<String, serde_json::Value> {
        let mut changes = HashMap::new();
        if self.room_state != other.room_state {
            let mut m = HashMap::new();
            m.insert("from".to_string(), serde_json::json!(other.room_state));
            m.insert("to".to_string(), serde_json::json!(self.room_state));
            changes.insert("room_state".to_string(), serde_json::json!(m));
        }
        if self.player != other.player {
            let mut m = HashMap::new();
            m.insert("from".to_string(), serde_json::json!([other.player.0, other.player.1]));
            m.insert("to".to_string(), serde_json::json!([self.player.0, self.player.1]));
            changes.insert("player".to_string(), serde_json::json!(m));
        }
        if self.boxes != other.boxes {
            let from_boxes: Vec<Vec<i32>> = other.boxes.iter().map(|p| vec![p.0, p.1]).collect();
            let to_boxes: Vec<Vec<i32>> = self.boxes.iter().map(|p| vec![p.0, p.1]).collect();
            let mut m = HashMap::new();
            m.insert("from".to_string(), serde_json::json!(from_boxes));
            m.insert("to".to_string(), serde_json::json!(to_boxes));
            changes.insert("boxes".to_string(), serde_json::json!(m));
        }
        if self.boxes_on_target != other.boxes_on_target {
            let mut m = HashMap::new();
            m.insert("from".to_string(), serde_json::json!(other.boxes_on_target));
            m.insert("to".to_string(), serde_json::json!(self.boxes_on_target));
            changes.insert("boxes_on_target".to_string(), serde_json::json!(m));
        }
        if self.done != other.done {
            let mut m = HashMap::new();
            m.insert("from".to_string(), serde_json::json!(other.done));
            m.insert("to".to_string(), serde_json::json!(self.done));
            changes.insert("done".to_string(), serde_json::json!(m));
        }
        changes
    }
}

#[derive(Debug, Clone)]
pub struct PrivateState {
    pub episode_id: String,
    pub task_id: String,
    pub puzzle_id: String,
    pub seed: i32,
    pub config_hash: String,
    pub step_index: i32,
    pub reward_last: f64,
    pub total_reward: f64,
    pub terminated: bool,
    pub truncated: bool,
    pub achievements: BTreeSet<String>,
}

impl PrivateState {
    pub fn new(
        episode_id: String,
        task_id: String,
        puzzle_id: String,
        seed: i32,
        config_hash: String,
    ) -> Self {
        Self {
            episode_id,
            task_id,
            puzzle_id,
            seed,
            config_hash,
            step_index: 0,
            reward_last: 0.0,
            total_reward: 0.0,
            terminated: false,
            truncated: false,
            achievements: BTreeSet::new(),
        }
    }

    pub fn to_json_value(&self) -> serde_json::Value {
        let sorted_ach: Vec<String> = self.achievements.iter().cloned().collect();
        serde_json::json!({
            "episode_id": self.episode_id,
            "task_id": self.task_id,
            "puzzle_id": self.puzzle_id,
            "seed": self.seed,
            "config_hash": self.config_hash,
            "step_index": self.step_index,
            "reward_last": self.reward_last,
            "total_reward": self.total_reward,
            "terminated": self.terminated,
            "truncated": self.truncated,
            "achievements": sorted_ach,
        })
    }
}

// Helper type alias
use std::collections::HashMap;

// Task resolution - ported from gold_python/task_resolve.py

use sha2::{Sha256, Digest};
use std::collections::HashMap;

pub const WALL: i32 = 0;
pub const FLOOR: i32 = 1;
pub const TARGET: i32 = 2;
pub const BOX_ON_TARGET: i32 = 3;
pub const BOX: i32 = 4;
pub const PLAYER: i32 = 5;
pub const PLAYER_ON_TARGET: i32 = 6;

#[derive(Debug, Clone)]
pub struct ResolvedTask {
    pub task_id: String,
    pub puzzle_id: String,
    pub seed: i32,
    pub config_hash: String,
    pub room_fixed: Vec<Vec<i32>>,
    pub room_state: Vec<Vec<i32>>,
    pub goals: Vec<(i32, i32)>,
    pub boxes: Vec<(i32, i32)>,
    pub player: (i32, i32),
    pub max_steps: i32,
    pub rewards: HashMap<String, f64>,
    pub errors: HashMap<String, serde_json::Value>,
    pub curriculum: HashMap<String, serde_json::Value>,
    pub monty_reward: HashMap<String, serde_json::Value>,
    pub resolved_json: HashMap<String, serde_json::Value>,
}

impl ResolvedTask {
    pub fn to_json_value(&self) -> serde_json::Value {
        serde_json::json!({
            "task_id": self.task_id,
            "puzzle_id": self.puzzle_id,
            "seed": self.seed,
            "config_hash": self.config_hash,
            "room_fixed": self.room_fixed,
            "room_state": self.room_state,
            "goals": self.goals.iter().map(|(r,c)| vec![*r, *c]).collect::<Vec<_>>(),
            "boxes": self.boxes.iter().map(|(r,c)| vec![*r, *c]).collect::<Vec<_>>(),
            "player": [self.player.0, self.player.1],
            "max_steps": self.max_steps,
            "rewards": self.rewards,
            "errors": self.errors,
            "curriculum": self.curriculum,
            "monty_reward": self.monty_reward,
            "resolved_json": self.resolved_json,
        })
    }
}

// === Default rules data ===

fn sparse_sokoban_rules_value() -> serde_json::Value {
    serde_json::json!({
        "max_steps": 120,
        "push_semantics": "standard",
        "rewards": {
            "step": -0.01,
            "push": 0.0,
            "box_on_target": 0.1,
            "goal": 1.0,
            "blocked": -0.02
        },
        "errors": {
            "mode": "silent"
        },
        "achievements": {
