}

// === Curriculum levels ===
// NOTE: These MUST match gold_python/task_resolve.py's CURRICULUM_EASY_LEVELS
// exactly. No "name" or "optimal_steps" keys (the Python gold uses chosen.get
// which returns None/null for missing keys).

const CURRICULUM_EASY_LEVELS: &[(&str, &[&str])] = &[
    ("lvl-01-corner", &["#####", "#@$.#", "#####"]),
    ("lvl-02-corridor", &["#######", "#@$.. #", "#######"]),
    ("lvl-03-t", &["#####", "#@  #", "# $ #", "#  .#", "#####"]),
    ("lvl-04-walls", &["######", "#@  .#", "# ## #", "# $  #", "######"]),
    ("lvl-05-double", &["#######", "#@$.  #", "#     #", "# $.  #", "#######"]),
    ("seed-101", &["######", "#@ $ #", "#   .#", "######"]),
    ("seed-102", &["#####", "#@  #", "# $ #", "# . #", "#####"]),
    ("seed-103", &["######", "#@   #", "# $$ #", "# .. #", "######"]),
    ("seed-104", &["########", "#@ $  .#", "########"]),
    ("seed-105", &["#######", "#@ $  #", "#  $ .#", "#    .#", "#######"]),
    ("seed-106", &["######", "#@   #", "###$ #", "#  . #", "######"]),
    ("seed-107", &["#######", "#@    #", "# $$  #", "# ..  #", "#######"]),
    ("seed-108", &["######", "# .  #", "# $@ #", "######"]),
    ("seed-109", &["#####", "#@  #", "# $ #", "# $ #", "# . #", "# . #", "#####"]),
    ("seed-110", &["######", "#@ $ #", "# .  #", "######"]),
];

// === ASCII grid parsing ===

pub fn ascii_to_int_grids(
    rows: &[String],
) -> (Vec<Vec<i32>>, Vec<Vec<i32>>, Vec<(i32, i32)>, Vec<(i32, i32)>, (i32, i32)) {
    let width = rows.iter().map(|r| r.len()).max().unwrap_or(0);
    let mut room_fixed: Vec<Vec<i32>> = Vec::new();
    let mut room_state: Vec<Vec<i32>> = Vec::new();
    let mut goals: Vec<(i32, i32)> = Vec::new();
    let mut boxes: Vec<(i32, i32)> = Vec::new();
    let mut player: Option<(i32, i32)> = None;

    for (r, raw_row) in rows.iter().enumerate() {
        let mut fixed_row = Vec::new();
        let mut state_row = Vec::new();
        let padded = format!("{:width$}", raw_row, width = width);
        for (c, ch) in padded.chars().enumerate() {
            match ch {
                '#' => {
                    fixed_row.push(WALL);
                    state_row.push(WALL);
                }
                '.' | 'G' => {
                    fixed_row.push(TARGET);
                    state_row.push(TARGET);
                    goals.push((r as i32, c as i32));
                }
                '*' => {
                    fixed_row.push(TARGET);
                    state_row.push(BOX_ON_TARGET);
                    goals.push((r as i32, c as i32));
                    boxes.push((r as i32, c as i32));
                }
                '+' => {
                    fixed_row.push(TARGET);
                    state_row.push(PLAYER_ON_TARGET);
                    goals.push((r as i32, c as i32));
                    player = Some((r as i32, c as i32));
                }
                '$' => {
                    fixed_row.push(FLOOR);
                    state_row.push(BOX);
                    boxes.push((r as i32, c as i32));
                }
                '@' => {
                    fixed_row.push(FLOOR);
                    state_row.push(PLAYER);
                    player = Some((r as i32, c as i32));
                }
                _ => {
                    fixed_row.push(FLOOR);
                    state_row.push(FLOOR);
                }
            }
        }
        room_fixed.push(fixed_row);
        room_state.push(state_row);
    }

    let player = player.expect("sokoban map has no player");
    assert!(!goals.is_empty(), "sokoban map has no goals");
    assert!(!boxes.is_empty(), "sokoban map has no boxes");

    (room_fixed, room_state, goals, boxes, player)
}

pub fn grid_to_ascii(
    room_fixed: &[Vec<i32>],
    player: (i32, i32),
    boxes: &std::collections::BTreeSet<(i32, i32)>,
) -> Vec<String> {
    let mut rows = Vec::new();
    for (r, fixed_row) in room_fixed.iter().enumerate() {
        let mut chars = Vec::new();
        for (c, &fixed) in fixed_row.iter().enumerate() {
            let pos = (r as i32, c as i32);
            let on_target = fixed == TARGET;
            if fixed == WALL {
                chars.push('#');
            } else if pos == player {
                chars.push(if on_target { '+' } else { '@' });
            } else if boxes.contains(&pos) {
                chars.push(if on_target { '*' } else { '$' });
            } else if on_target {
                chars.push('.');
            } else {
                chars.push(' ');
            }
        }
        let s: String = chars.iter().collect();
        rows.push(s.trim_end().to_string());
    }
    rows
}

// === Deep merge helper ===

fn deep_merge_value(target: &mut serde_json::Value, source: &serde_json::Value) {
    match (target, source) {
        (serde_json::Value::Object(tgt), serde_json::Value::Object(src)) => {
            for (key, src_val) in src {
                if let Some(tgt_val) = tgt.get_mut(key) {
                    deep_merge_value(tgt_val, src_val);
                } else {
                    tgt.insert(key.clone(), src_val.clone());
                }
            }
        }
        (tgt, src) => {
            *tgt = src.clone();
        }
    }
}

// === Resolve rules ===

fn resolve_rules_value(rules_spec: &serde_json::Value) -> serde_json::Value {
    let mut merged = sparse_sokoban_rules_value();

    if let Some(overrides) = rules_spec.get("overrides") {
        deep_merge_value(&mut merged, overrides);
    }

    merged
}

// === Resolve map ===
// Matches Python gold's _resolve_map exactly (simplified version without JSON file loading)

fn resolve_map(map_spec: &serde_json::Value, seed: i32) -> (String, serde_json::Value, serde_json::Value) {
    let source = map_spec.get("source").and_then(|v| v.as_str()).unwrap_or("");

    if source == "inline" || map_spec.get("grid").is_some() {
        let grid_val = map_spec.get("grid").expect("inline map must have grid");
        let puzzle_id = map_spec
            .get("puzzle_id")
            .and_then(|v| v.as_str())
            .unwrap_or("inline")
            .to_string();
        let metadata = map_spec.get("metadata").cloned().unwrap_or(serde_json::json!({}));
        return (puzzle_id, grid_val.clone(), metadata);
    }

    let default_name = map_spec
        .get("use_default")
        .and_then(|v| v.as_str())
        .unwrap_or("curriculum_easy")
        .to_string();

    let levels = CURRICULUM_EASY_LEVELS;

    let has_seed = map_spec.get("seed").is_some() || seed != 0;
    let index = if has_seed {
        let s = map_spec.get("seed").and_then(|v| v.as_i64()).unwrap_or(seed as i64);
        (s as usize) % levels.len()
    } else {
        let idx = map_spec.get("index").and_then(|v| v.as_i64()).unwrap_or(0);
        (idx as usize) % levels.len()
    };

    let (id, grid_ref) = &levels[index];
    let grid_lines: Vec<String> = grid_ref.iter().map(|s| s.to_string()).collect();

    let puzzle_id = id.to_string();

    // Build metadata exactly matching Python gold:
    // chosen.get("name", chosen["id"]) -> since no "name" key, returns chosen["id"]
    // chosen.get("optimal_steps") -> since no key, returns None -> JSON null
    let opt_steps: Option<i32> = None;
    let metadata = serde_json::json!({
        "default": default_name,
        "index": index,
        "name": puzzle_id,
        "optimal_steps": opt_steps,
    });

    let grid_val = serde_json::json!(grid_lines);

    (puzzle_id, grid_val, metadata)
}

// === Main resolve function ===

pub fn resolve_task(task: &HashMap<String, serde_json::Value>, seed_override: Option<i32>) -> ResolvedTask {
    let seed = match seed_override {
        Some(s) => s,
        None => {
            task.get("seed")
                .and_then(|v| v.as_i64())
                .or_else(|| {
                    task.get("map")
                        .and_then(|m| m.get("seed"))
                        .and_then(|v| v.as_i64())
                })
                .unwrap_or(0) as i32
        }
    };

    let task_id = task
        .get("task_id")
        .and_then(|v| v.as_str())
        .unwrap_or("sokoban_manual")
        .to_string();

    let map_spec = task.get("map").cloned().unwrap_or(serde_json::json!({}));

    // Resolve map
    let (puzzle_id, grid_val, metadata) = resolve_map(&map_spec, seed);

    // Resolve rules
    let rules_spec = task.get("rules").cloned().unwrap_or(serde_json::json!({"base": "sparse_sokoban"}));
    let merged_rules = resolve_rules_value(&rules_spec);

    let grid_rows: Vec<String> = match &grid_val {
        serde_json::Value::Array(arr) => {
            arr.iter().map(|v| v.as_str().unwrap_or("").to_string()).collect()
        }
        _ => panic!("grid must be array"),
    };

    let (room_fixed, room_state, goals, boxes, player) = ascii_to_int_grids(&grid_rows);

    // Build the resolved dict for config_hash
    let mut resolved_map = serde_json::Map::new();
    resolved_map.insert("schema".to_string(), serde_json::json!("gamebench.task.sokoban.v1"));
    resolved_map.insert("task_id".to_string(), serde_json::json!(task_id));
    resolved_map.insert("seed".to_string(), serde_json::json!(seed));

    let mut map_entry = serde_json::Map::new();
    map_entry.insert("puzzle_id".to_string(), serde_json::json!(puzzle_id));
    map_entry.insert("grid".to_string(), grid_val.clone());
    map_entry.insert("metadata".to_string(), metadata.clone());
    resolved_map.insert("map".to_string(), serde_json::json!(map_entry));

    // Use the FULLY MERGED rules (with achievements, max_steps, etc.)
    resolved_map.insert("rules".to_string(), merged_rules.clone());

    let readouts = task
        .get("readouts")
        .cloned()
        .unwrap_or(serde_json::json!({"symbolic": "ascii_annotated", "visual": false}));
    resolved_map.insert("readouts".to_string(), readouts);

    let checkpoint_every_n_steps = task
        .get("checkpoint_every_n_steps")
        .and_then(|v| v.as_i64())
        .unwrap_or(1);
    resolved_map.insert("checkpoint_every_n_steps".to_string(), serde_json::json!(checkpoint_every_n_steps));

    // Serialize to canonical JSON string (sort_keys=True, separators=(",",":"))
    let canonical = serde_json::to_string(&serde_json::Value::Object(resolved_map.clone())).unwrap();
    let mut hasher = Sha256::new();
    hasher.update(canonical.as_bytes());
    let digest = format!("{:x}", hasher.finalize());
    let config_hash = format!("sha256:{}", digest);

    let max_steps = merged_rules
        .get("max_steps")
        .and_then(|v| v.as_i64())
        .unwrap_or(120) as i32;

    let rewards_map: HashMap<String, f64> = merged_rules
        .get("rewards")
        .and_then(|v| v.as_object())
        .map(|obj| {
            obj.iter()
                .map(|(k, v)| (k.clone(), v.as_f64().unwrap_or(0.0)))
                .collect()
        })
        .unwrap_or_default();

    let errors: HashMap<String, serde_json::Value> = merged_rules
        .get("errors")
        .and_then(|v| v.as_object())
        .map(|obj| obj.iter().map(|(k, v)| (k.clone(), v.clone())).collect())
        .unwrap_or_default();

    let curriculum: HashMap<String, serde_json::Value> = metadata
        .as_object()
        .map(|obj| obj.iter().map(|(k, v)| (k.clone(), v.clone())).collect())
        .unwrap_or_default();

    let monty_reward: HashMap<String, serde_json::Value> = HashMap::new();
    let resolved_json: HashMap<String, serde_json::Value> = resolved_map.into_iter().collect();

    ResolvedTask {
        task_id,
        puzzle_id,
        seed,
        config_hash,
        room_fixed,
        room_state,
        goals,
        boxes,
        player,
        max_steps,
        rewards: rewards_map,
        errors,
        curriculum,
        monty_reward,
        resolved_json,
    }
}
